//! The port against the upstream calculator's own output (`fixtures/ballistics/golden.json`,
//! generated by running the upstream `math.ts`): every
//! projectile of the gun data, maximum range, low and high arcs, landing range, submunition and
//! blast diameters, azimuth and distance. A value matches within the fixture's absolute tolerance
//! or its relative one; missing values (no arc, despawned) must be missing in both.

use mtc_ballistics::{Ballistics, Projectile, azimuth, blast_diameter, distance, landing_range, submunition_blast_diameter};
use serde::Deserialize;

#[derive(Deserialize)]
struct Golden {
    tolerance: Tolerance,
    geometry: Vec<Geometry>,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Tolerance {
    elevation_deg: f64,
    time_of_flight_s: f64,
    range_m: f64,
    relative: f64,
}

#[derive(Deserialize)]
struct Geometry {
    from: [f64; 2],
    to: [f64; 2],
    azimuth: f64,
    distance: f64,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    projectile: NamedProjectile,
    max_range: Vec<HeightRange>,
    arcs: Vec<ArcCase>,
    landing_range: Vec<LandingCase>,
    submunition: Vec<SubmunitionCase>,
    blast_diameter: Option<f64>,
}

#[derive(Deserialize)]
struct NamedProjectile {
    name: String,
    #[serde(flatten)]
    physics: Projectile,
}

#[derive(Deserialize)]
struct HeightRange {
    h: f64,
    range: Option<f64>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct GoldenArc {
    elevation: f64,
    time_of_flight: f64,
}

#[derive(Deserialize)]
struct ArcCase {
    d: f64,
    h: f64,
    low: Option<GoldenArc>,
    high: Option<GoldenArc>,
}

#[derive(Deserialize)]
struct LandingCase {
    elevation: f64,
    h: f64,
    range: Option<f64>,
}

#[derive(Deserialize)]
struct SubmunitionCase {
    elevation: f64,
    h: f64,
    diameter: Option<f64>,
}

struct Check {
    tolerance: f64,
    relative: f64,
    passed: u32,
    failed: Vec<String>,
}

impl Check {
    fn value(&mut self, case: &str, got: f64, want: Option<f64>) {
        let ok = match want {
            None => !got.is_finite(),
            Some(w) => got.is_finite() && ((got - w).abs() <= self.tolerance || (got - w).abs() <= self.relative * w.abs()),
        };
        if ok {
            self.passed += 1;
        } else {
            self.failed.push(format!("{case}: got {got}, want {want:?}"));
        }
    }

    fn report(&self, what: &str) -> bool {
        println!("{what}: {}/{}", self.passed, self.passed as usize + self.failed.len());
        for f in self.failed.iter().take(10) {
            println!("  FAIL {f}");
        }
        self.failed.is_empty()
    }
}

#[test]
fn port_reproduces_the_upstream_calculator() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/ballistics/golden.json");
    let golden: Golden = serde_json::from_str(&std::fs::read_to_string(path).expect("golden fixture")).expect("parse");
    let t = &golden.tolerance;
    let new = |tolerance: f64| Check { tolerance, relative: t.relative, passed: 0, failed: Vec::new() };
    let (mut ranges, mut elevations, mut times, mut landings, mut diameters, mut geometry) =
        (new(t.range_m), new(t.elevation_deg), new(t.time_of_flight_s), new(t.range_m), new(t.range_m), new(t.range_m));
    let started = std::time::Instant::now();
    for case in &golden.cases {
        let name = &case.projectile.name;
        let p = &case.projectile.physics;
        let b = Ballistics::new(p.clone());
        for m in &case.max_range {
            ranges.value(&format!("{name} max range h {}", m.h), b.max_range(m.h), m.range);
        }
        for a in &case.arcs {
            let (low, high) = b.arcs(a.d, a.h);
            for (side, got, want) in [("low", low, &a.low), ("high", high, &a.high)] {
                let label = format!("{name} {side} arc d {:.1} h {}", a.d, a.h);
                elevations.value(&label, got.map_or(f64::NAN, |g| g.elevation), want.as_ref().map(|w| w.elevation));
                times.value(&label, got.map_or(f64::NAN, |g| g.time_of_flight), want.as_ref().map(|w| w.time_of_flight));
            }
        }
        for l in &case.landing_range {
            landings.value(&format!("{name} landing {}° h {}", l.elevation, l.h), landing_range(p, l.elevation, l.h), l.range);
        }
        for s in &case.submunition {
            diameters.value(&format!("{name} submunitions {}°", s.elevation), submunition_blast_diameter(p, s.elevation, s.h), s.diameter);
        }
        if let (Some(mass), Some(want)) = (p.explosive_mass, case.blast_diameter) {
            diameters.value(&format!("{name} blast"), blast_diameter(mass, 1.0, 1.0, 0.07), Some(want));
        }
    }
    for g in &golden.geometry {
        geometry.value("azimuth", azimuth(g.from[0], g.from[1], g.to[0], g.to[1]), Some(g.azimuth));
        geometry.value("distance", distance(g.from[0], g.from[1], g.to[0], g.to[1], 0.0, 0.0), Some(g.distance));
    }
    println!("{} projectiles in {:.1} s", golden.cases.len(), started.elapsed().as_secs_f64());
    let ok = [
        ranges.report("max range"),
        elevations.report("arc elevation"),
        times.report("arc time of flight"),
        landings.report("landing range"),
        diameters.report("submunition and blast diameters"),
        geometry.report("azimuth and distance"),
    ];
    assert!(ok.iter().all(|&o| o), "the port differs from the upstream calculator");
}
